"""Native rotor rigidity, static gearbox, clear portals, deck pose and CAMERA UI."""
import argparse,hashlib,json,sys
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT=Path(__file__).resolve().parents[3];sys.path.insert(0,str(ROOT/'docs/multiship/G'))
from browser_g import launch,load_fleet
RIG_FIXTURE=r'''()=>{
 const v=__WIP148_3D_VIEW__,T=v.THREE,s=get3DRenderState(),h=s.helicopters.aircraft[0],row=v.heloVisualsA.get(h.id),before=JSON.stringify(__HELO__.snapshot()),checks={},samples=[],gear=row.instance.parts.get(12821);
 const metrics=()=>{row.root.updateWorldMatrix(true,true);return Object.fromEntries(['main','tail'].map(name=>{const r=row.rotors[name],inverse=row.root.matrixWorld.clone().invert(),points=[];for(const id of r.config.bladeIds){const group=row.instance.parts.get(id);group.traverse(mesh=>{if(!mesh.isMesh)return;const p=mesh.geometry.attributes.position,m=inverse.clone().multiply(mesh.matrixWorld);for(let i=0;i<p.count;i+=Math.max(1,Math.floor(p.count/8))){const q=new T.Vector3().fromBufferAttribute(p,i).applyMatrix4(m).sub(new T.Vector3(...r.config.centerM)),ax=q.dot(r.axis);points.push({ax,rad:q.clone().addScaledVector(r.axis,-ax).length()});}});}return [name,points];}));};
 for(const angle of [0,Math.PI/4,Math.PI/2,Math.PI,Math.PI*1.5]){const st=structuredClone(s);st.helicopters.aircraft[0].rotorAngleRad=angle;v.syncShipFittings(st);row.root.updateWorldMatrix(true,true);samples.push({angle,metrics:metrics(),gear:gear.matrixWorld.elements.slice()});}
 for(const name of ['main','tail'])checks[name+'RigidAboutOwnAxis']=samples.every(sample=>sample.metrics[name].every((p,i)=>Math.abs(p.ax-samples[0].metrics[name][i].ax)<1e-6&&Math.abs(p.rad-samples[0].metrics[name][i].rad)<1e-6));
 checks.gearboxDoesNotSpin=samples.every(a=>a.gear.every((n,i)=>Math.abs(n-samples[0].gear[i])<1e-8));checks.tailOnlyHubAndBlades=gear.parent!==row.tailSpin&&row.tailSpin.children.filter(p=>p.userData.sourceNode).length===5;
 checks.rotorsOutsideNonuniformScale=row.spin.parent===row.root&&row.tailSpin.parent===row.root;checks.blurNormalsMatchAxes=Object.values(row.rotors).every(r=>Math.abs(new T.Vector3(0,0,1).applyQuaternion(r.disk.quaternion).dot(r.axis)-1)<1e-7);
 checks.renderHasNoSimWrites=before===JSON.stringify(__HELO__.snapshot());v.syncShipFittings(s);return {checks,samples};
}'''
DOORS=r'''slot=>{const v=__WIP148_3D_VIEW__,T=v.THREE,root=v.shipRoot;root.updateWorldMatrix(true,true);const blockers=[];
 const visible=o=>{for(let p=o;p;p=p.parent)if(!p.visible)return false;return true;};
 for(const y of [3.6,5,7.5])for(const z of [(slot===0?-1:1)*5.03-1.4,(slot===0?-1:1)*5.03,(slot===0?-1:1)*5.03+1.4]){
  const origin=root.localToWorld(new T.Vector3(-53,y,z)),direction=new T.Vector3(1,0,0).transformDirection(root.matrixWorld),ray=new T.Raycaster(origin,direction,0,7);for(const h of ray.intersectObject(root,true)){if(!visible(h.object))continue;const p=root.worldToLocal(h.point.clone());if(p.x>-49&&p.x<-47.2)blockers.push({mesh:h.object.name,parent:h.object.parent?.name,p:p.toArray()});}
 }return {slot,blockers,changedMeshes:v.heloDoorsA?.changedMeshes};}'''
def main():
 p=argparse.ArgumentParser();p.add_argument('html',type=Path);p.add_argument('out',type=Path);a=p.parse_args();a.out.mkdir(parents=True,exist_ok=True);errors=[];checks={};records={}
 with sync_playwright()as pw:
  b=launch(pw,True);page=load_fleet(b,a.html.read_bytes(),own='DDG_119_LATE_FLIGHT_IIA',ally=None,enemy=None,webgl=False,errors=errors)
  page.locator('#modeAirBtn').click();page.locator('#airHeloA0').click();page.locator('#airLaunchA').click();page.locator('#airHeloA1').click();page.wait_for_timeout(300);page.locator('#airLaunchA').click();page.locator('#airHeloA0').click();page.evaluate('__NAVAL_SIM_DIAG__.stepTicks(600)');page.locator('#airViewA').click();page.wait_for_function('__WIP148_3D_VIEW__.heloVisualsA.size===1',timeout=90000)
  page.evaluate('''()=>{const v=__WIP148_3D_VIEW__;v.syncShipFittings(get3DRenderState());v.orbit.yaw=Math.PI/2;v.orbit.pitch=.1;v.orbit.distance=32;v.syncCamera();v.renderer.render(v.scene,v.camera);}''');records['portDoor']=page.evaluate(DOORS,0);checks['portPortalHasNoWall']=not records['portDoor']['blockers'];records['foldedBounds']=page.evaluate('''()=>{const v=__WIP148_3D_VIEW__,T=v.THREE,row=[...v.heloVisualsA.values()][0],box=new T.Box3();row.root.updateWorldMatrix(true,true);const inv=row.root.matrixWorld.clone().invert();row.root.traverse(m=>{if(!m.isMesh)return;for(let p=m;p&&p!==row.root;p=p.parent)if(!p.visible)return;const a=m.geometry.attributes.position,tr=inv.clone().multiply(m.matrixWorld),q=new T.Vector3();for(let i=0;i<a.count;i++)box.expandByPoint(q.fromBufferAttribute(a,i).applyMatrix4(tr));});return {min:box.min.toArray(),max:box.max.toArray()};}''');checks['foldedEnvelopeMatchesSource']=all(abs(a-b)<.06 for a,b in zip(records['foldedBounds']['min']+records['foldedBounds']['max'],[-4.494,-.001,-1.505,7.990,4.962,2.239]));page.screenshot(path=str(a.out/'port-open.png'))
  page.evaluate('__NAVAL_SIM_DIAG__.stepTicks(900)');page.wait_for_timeout(200);page.screenshot(path=str(a.out/'turning.png'))
  page.evaluate('__NAVAL_SIM_DIAG__.stepTicks(2100)');page.wait_for_timeout(200);records['rig']=page.evaluate(RIG_FIXTURE);checks.update(records['rig']['checks'])
  checks['cameraLazyInitDistance']=page.evaluate('__WIP148_3D_VIEW__.orbit.distance===32')
  page.evaluate('''()=>{const v=__WIP148_3D_VIEW__;v.orbit.yaw=.6;v.orbit.pitch=.4;v.orbit.distance=38;v.syncCamera();v.renderer.render(v.scene,v.camera);}''');page.screenshot(path=str(a.out/'deployed.png'))
  page.evaluate('__NAVAL_SIM_DIAG__.stepTicks(4900)');page.wait_for_function('__WIP148_3D_VIEW__.heloVisualsA.size===2',timeout=90000);page.locator('#c14ControlsToggle').click();page.locator('#c15CameraCategory').click();page.locator('#external3DHeloB1').click();page.wait_for_timeout(200)
  checks['cameraMenuTracksSecond']=page.evaluate('__WIP148_3D_VIEW__.heloFocusA===__HELO__.snapshot().aircraft[1].id');checks['cameraTargetDistance']=page.evaluate('__WIP148_3D_VIEW__.orbit.distance===42');checks['sharedGeometryLease']=page.evaluate('__WIP148_3D_VIEW__.heloVisualsA.size===2&&__WIP148_3D_VIEW__.heloLeaseA.geometries.length===77')
  # H2 has at least a full ten seconds to open by this tick; sync read-only data.
  page.evaluate('''()=>{const v=__WIP148_3D_VIEW__;v.syncShipFittings(get3DRenderState());}''');records['starboardDoor']=page.evaluate(DOORS,1);checks['starboardPortalHasNoWall']=not records['starboardDoor']['blockers'];page.screenshot(path=str(a.out/'camera-second.png'))
  checks['geometryAttributesAndGl']=page.evaluate('''()=>{const v=__WIP148_3D_VIEW__;let bad=0;v.shipRoot.traverse(o=>{if(!o.isMesh)return;const a=o.geometry.attributes;if(a.normal&&a.normal.count!==a.position.count)bad++;if(a.color&&a.color.count<a.position.count)bad++;});for(const m of v.heloVisualsA.values())m.root.traverse(o=>{if(!o.matrix.elements.every(Number.isFinite))bad++;});return !bad&&v.renderer.getContext().getError()===0;}''')
  page.evaluate('''()=>{__NAVAL_SIM_DIAG__.resetEntireSessionV48Wip11A();const v=__WIP148_3D_VIEW__,s=get3DRenderState();v.syncWorldEpochWip14A(s);v.syncShipFittings(s);}''');checks['resetRetiresAllModels']=page.evaluate('__WIP148_3D_VIEW__.heloVisualsA.size===0&&__WIP148_3D_VIEW__.heloLeaseA===null&&__WIP148_3D_VIEW__.heloRotorGeosB===null');checks['corePass']=page.evaluate('__CORE_SELFTEST_FAILURES__.length===0');b.close()
 out={'pass':all(checks.values())and not errors,'checks':checks,'records':records,'errors':errors,'htmlSha256':hashlib.sha256(a.html.read_bytes()).hexdigest(),'limits':'Native Three/SwiftShader, not hardware FPS. Rotor angle samples operate on detached render snapshots; physics unchanged.'};(a.out/'native.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'pass':out['pass'],'checks':len(checks),'failed':[k for k,v in checks.items()if not v],'errors':errors}));raise SystemExit(0 if out['pass']else 1)
if __name__=='__main__':main()
